import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ZoomOutImpacto: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const src = String(anim.params?.src ?? "");
  const rawZoom = Number(anim.params?.zoomFrom);
  const zoomFrom = Number.isFinite(rawZoom) && rawZoom > 1 ? Math.min(rawZoom, 4) : 1.6;

  const dur = Math.max(2, Math.round((anim.end - anim.start) * fps));
  // Fast punch-out over ~0.35s (never more than 30% of the layer), then a slow settle.
  const fastEnd = Math.max(1, Math.min(Math.round(0.35 * fps), Math.floor(dur * 0.3)));
  const mid = 1 + (zoomFrom - 1) * 0.2;

  const scale = interpolate(f, [0, fastEnd, dur], [zoomFrom, mid, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const opacity = interpolate(f, [0, Math.max(1, Math.round(fps * 0.12))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  return (
    <AbsoluteFill style={{ overflow: "hidden", opacity }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${scale})`,
          transformOrigin: "50% 50%",
        }}
      >
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
        ) : (
          <AbsoluteFill
            style={{
              alignItems: "center",
              justifyContent: "center",
              backgroundColor: "rgba(255,255,255,0.06)",
              border: `${Math.max(2, Math.round(Math.min(frame.width, frame.height) * 0.004))}px dashed ${muted}`,
              boxSizing: "border-box",
            }}
          >
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontStyle: "italic",
                textTransform: "uppercase",
                color: muted,
                fontSize: Math.round(Math.min(frame.width, frame.height) * 0.06),
                textAlign: "center",
                padding: "0 6%",
              }}
            >
              Sem imagem
            </div>
          </AbsoluteFill>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ZoomOutImpacto;
